namespace Flagman;
public record ProcurementLine(string Id,string ProductId,decimal Quantity,string Unit);
public record ProcurementRequest(string Id,string AuthorId,string SupplierId,List<ProcurementLine> Items,DateTimeOffset? DesiredAt,string? Comment,DateTimeOffset CreatedAt,string Status="submitted",int Version=1,List<ProcurementResponseLine>? Response=null,string? DeliveryRequestId=null);
public record ProcurementRequestInput(string SupplierId,List<ProcurementLine> Items,DateTimeOffset? DesiredAt=null,string? Comment=null);
public record ProcurementResponseLine(string LineId,decimal ConfirmedQuantity,DateTimeOffset? ExpiresAt=null,string? ExpiryDate=null,DateTimeOffset? ManufacturedAt=null,decimal? ShelfLifeHours=null,decimal? UnitCost=null,string? Currency=null,string? Reason=null);
public record ProcurementResponseInput(int ExpectedVersion,List<ProcurementResponseLine> Items);
public record ProcurementResponseResult(ProcurementRequest ProcurementRequest,string? DeliveryRequestId);
public record VersionInput(int ExpectedVersion);
public record DeliveryRequestLine(string Id,string ProductId,decimal Quantity,string Unit,DateTimeOffset ExpiresAt,decimal? UnitCost=null,string? Currency=null,string? ProcurementLineId=null,DateTimeOffset? ManufacturedAt=null,decimal? ShelfLifeHours=null);
public record DeliveryRequest(string Id,string AuthorId,string Number,List<DeliveryRequestLine> Items,DateTimeOffset CreatedAt,string? ProcurementRequestId=null,string Status="submitted",int Version=1,List<DeliveryAcceptanceLine>? Acceptance=null,string? DeliveryId=null,string? DecisionActorId=null,DateTimeOffset? DecidedAt=null);
public record DeliveryRequestInput(string Number,List<DeliveryLine> Items);
public record DeliveryAcceptanceLine(string LineId,decimal AcceptedQuantity,DateTimeOffset? VerifiedExpiresAt=null,string? Reason=null);
public record DeliveryAcceptanceInput(int ExpectedVersion,List<DeliveryAcceptanceLine> Items);
public record OrderRequest(string Id,string AuthorId,List<OrderItem> Items,string RecipeFingerprint,DateTimeOffset CreatedAt,string Status="submitted",int Version=1,string? OrderId=null,string? Reason=null,List<Shortage>? Shortages=null,string? DecisionActorId=null,DateTimeOffset? DecidedAt=null,string? ServedById=null,DateTimeOffset? ServedAt=null,List<BatchReservation>? Reservations=null,OrderRejection? Rejection=null,List<RejectionProduct>? IngredientProducts=null);
public record BatchReservation(string BatchId,decimal Quantity);
public record OrderRequestInput(List<OrderItem> Items);
public record RejectionProduct(string Id,string Name);
public record OrderRejection(string Code,List<RejectionProduct> Products,string? Comment=null);
public record OrderDecisionInput(int ExpectedVersion,string Decision,string? Reason=null,string? ReasonCode=null,List<string>? ProductIds=null);
public record OfferOverride(string Id,string Visibility,bool Emphasized,string? WaiterNote,int Version=1);
public record OfferInput(string Visibility,bool Emphasized,string? WaiterNote,int ExpectedVersion);
public record PublishedOffer(string DishId,string Name,string Category,int AvailablePortions,string Visibility,bool Emphasized,string? WaiterNote,string? UnavailableReason);
public record WriteOffResult(string BatchId,decimal Quantity,string MovementId);
